using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using StateLandGovernance.GovernanceIntelligence.Infrastructure.Persistence.Entities;
namespace StateLandGovernance.GovernanceIntelligence.Infrastructure.Persistence.Configurations;
public sealed class ScreeningEvidenceAttachmentConfiguration:IEntityTypeConfiguration<ScreeningEvidenceAttachmentEntity>{public void Configure(EntityTypeBuilder<ScreeningEvidenceAttachmentEntity>b){
 b.ToTable("screening_evidence_attachments",t=>{t.HasCheckConstraint("ck_screening_attachment_bytes","octet_length(\"Content\") BETWEEN 1 AND 5242880");t.HasCheckConstraint("ck_screening_attachment_hashes","length(\"ContentSha256\")=64 AND length(\"InputSha256\")=64");t.HasCheckConstraint("ck_screening_attachment_type","\"ContentType\" IN ('application/pdf','image/png','image/jpeg','text/plain')");});b.HasKey(x=>x.Id);b.HasIndex(x=>new{x.CreatorActorId,x.SubmissionKey}).IsUnique();b.HasIndex(x=>new{x.RequestId,x.CreatedAtUtc});b.Property(x=>x.Concern).HasMaxLength(100);b.Property(x=>x.FileName).HasMaxLength(150);b.Property(x=>x.ContentType).HasMaxLength(50);b.Property(x=>x.ContentSha256).HasMaxLength(64);b.Property(x=>x.InputSha256).HasMaxLength(64);
 b.HasOne<OfficerAssessmentRequestEntity>().WithMany().HasForeignKey(x=>new{x.RequestId,x.CreatorActorId}).HasPrincipalKey(x=>new{x.Id,x.CreatorActorId}).OnDelete(DeleteBehavior.Restrict);
}}
public sealed class ScreeningEvidenceVerificationConfiguration:IEntityTypeConfiguration<ScreeningEvidenceVerificationEntity>{public void Configure(EntityTypeBuilder<ScreeningEvidenceVerificationEntity>b){
 b.ToTable("screening_evidence_verifications",t=>{t.HasCheckConstraint("ck_screening_verification_revision","\"Revision\">0 AND ((\"Revision\"=1 AND \"PreviousEventId\" IS NULL AND \"PreviousStatus\"='Unverified') OR (\"Revision\">1 AND \"PreviousEventId\" IS NOT NULL))");t.HasCheckConstraint("ck_screening_verification_status","\"Status\" IN ('Verified','Rejected','MoreInformationRequired') AND \"PreviousStatus\" IN ('Unverified','Verified','Rejected','MoreInformationRequired')");t.HasCheckConstraint("ck_screening_verification_hash","length(\"InputSha256\")=64 AND length(\"EventSha256\")=64");t.HasCheckConstraint("ck_screening_verification_refs","jsonb_typeof(\"AttachmentIdsJson\")='array' AND jsonb_typeof(\"ReferencesJson\")='array' AND jsonb_array_length(\"AttachmentIdsJson\")<=10 AND jsonb_array_length(\"ReferencesJson\")<=10");t.HasCheckConstraint("ck_screening_verification_remarks","length(\"Remarks\") BETWEEN 20 AND 2000");});b.HasKey(x=>x.Id);b.HasAlternateKey(x=>new{x.Id,x.RequestId,x.Concern,x.CreatorActorId});b.HasIndex(x=>new{x.RequestId,x.Concern,x.Revision}).IsUnique();b.HasIndex(x=>new{x.CreatorActorId,x.SubmissionKey}).IsUnique();b.HasIndex(x=>x.PreviousEventId).IsUnique();b.Property(x=>x.Concern).HasMaxLength(100);b.Property(x=>x.Status).HasMaxLength(32);b.Property(x=>x.PreviousStatus).HasMaxLength(32);b.Property(x=>x.Remarks).HasMaxLength(2000);b.Property(x=>x.InputSha256).HasMaxLength(64);b.Property(x=>x.EventSha256).HasMaxLength(64);b.Property(x=>x.AttachmentIdsJson).HasColumnType("jsonb");b.Property(x=>x.ReferencesJson).HasColumnType("jsonb");
 b.HasOne<OfficerAssessmentRequestEntity>().WithMany().HasForeignKey(x=>new{x.RequestId,x.CreatorActorId}).HasPrincipalKey(x=>new{x.Id,x.CreatorActorId}).OnDelete(DeleteBehavior.Restrict);
 b.HasOne<ScreeningEvidenceVerificationEntity>().WithMany().HasForeignKey(x=>new{x.PreviousEventId,x.RequestId,x.Concern,x.CreatorActorId}).HasPrincipalKey(x=>new{x.Id,x.RequestId,x.Concern,x.CreatorActorId}).OnDelete(DeleteBehavior.Restrict);
}}
